def run_deploy(hook, routes, batches):
    """Local Git test plumbing. Routing/deployment behavior comes from hook."""
    import os
    import shutil
    import subprocess
    import sys
    import tempfile
    with tempfile.TemporaryDirectory(prefix='medium30-git-deploy-') as td:
