 transform(payload, contract):\n    matrix = payload[\"matrix\"]\n    row_sizes = [row[0][\"rows\"] for row in matrix]\n    col_sizes = [matrix[0][j][\"cols\"] for j in range(len(matrix[0]))]\n    return {\"row_sizes\": row_sizes, \"col_sizes\": col_sizes}\n\n\ndef load_payload(path):\n    return json.loads(Path(path).read_text(encoding=\"utf-8\"))\n\n\ndef build_component(root, contract):\n    return build(root, contract, transform)\n"}","content_sha256":"[HASH]","delivery_verified":true,"materialized_files":{"engines/block_layout/engine.py":"[HASH]"},"tested_targets":[],"validated":false},{"artifact_id":"artifact-09421032c75349f6","branch_id":"v2-bf7cf624195a-1","content":"{"engines/squared/engine.py": "\"\"\"Implement the business transform. I/O helpers are supplied and editable here.\"\"\"\nfrom pathlib import Path\nimport json\nfrom runtime import build\n\n\ndef _block_value(block):\n    \"\"\"Return a dense rows x cols integer matrix for a block (null data = zeros).\"\"\"\n    rows = block[\"rows\"]\n    cols = block[\"cols\"]\n    if block[\"data\"] is None:\n        return [[0] * cols for _ in range(rows)]\n    return block[\"data\"]\n\n\ndef _matmul(a, b):\n    \"\"\"Multiply two dense integer matrices.\"\"\"\n    rows = len(a)\n    inner = len(b)\n    cols = len(b[0]) if inner else 0\n    out = [[0] * cols for _ in range(rows)]\n    for i in range(rows):\n        ai = a[i]\n        oi = out[i]\n        for k in range(inner):\n            aik = ai[k]\n            if aik:\n                bk = b[k]\n                for j in range(cols):\n                    oi[j] += aik * bk[j]\n    return out\n\n\ndef _is_zero(mat):\n    return all(v == 0 for row in mat for v in row)\n\n\ndef _block_multiply(a, b):\n    \"\"\"Multiply two blocks, returning a shaped block (data=null when all zero).\"\"\"\n    rows = a[\"rows\"]\n    cols = b[\"cols\"]\n    av = _block_value(a)\n    bv = _block_value(b)\n    prod = _matmul(av, bv)\n    if _is_zero(prod):\n        return {\"rows\": rows, \"cols\": cols, \"data\": None}\n    return {\"rows\": rows, \"cols\": cols, \"data\": prod}\n\n\ndef transform(payload, contract):\n    matrix = payload[\"matrix\"]\n    n = len(matrix)\n    result = []\n    for i in range(n):\n        row = []\n        for j in range(n):\n            acc = None\n            for k in range(n):\n                term = _block_multiply(matrix[i][k], matrix[k][j])\n                if acc is None:\n                    acc = term\n                else:\n                    av = _block_value(acc)\n                    bv = _block_value(term)\n                    summed = [[av[r][c] + bv[r][c] for c in range(len(av[0]))]\n                              for r in range(len(av))]\n                    if _is_zero(summed):\n                        acc = {\"rows\": acc[\"rows\"], \"cols\": acc[\"cols\"], \"data\": None}\n                    else:\n                        acc = {\"rows\": acc[\"rows\"], \"cols\": acc[\"cols\"], \"data\": summed}\n            row.append(acc)\n        result.append(row)\n    return result\n\n\ndef load_payload(path):\n    return json.loads(Path(path).read_text(encoding=\"utf-8\"))\n\n\ndef build_component(root, contract):\n    return build(root, contract, transform)\n"}","content_sha256":"[HASH]","delivery_verified":true,"materialized_files":{"engines/squared/engine.py":"[HASH]"},"tested_targets":[],"validated":false},{"artifact_id":"artifact-b004f98c1d3d626d","branch_id":"v2-bf7cf624195a-2","content":"{"engines/cubed/engine.py": "\"\"\"Implement the business transform. I/O helpers are supplied and editable here.\"\"\"\nfrom pathlib import Path\nimport json\nfrom runtime import build\n\n\ndef _block_value(block):\n    \"\"\"Return a dense integer matrix for a block, treating null data as zeros.\"\"\"\n    data = block[\"data\"]\n    rows = block[\"rows\"]\n    cols = block[\"cols\"]\n    if data is None:\n        return [[0] * cols for _ in range(rows)]\n    return data\n\n\ndef _multiply_blocks(a, b):\n 